const searchAssets = `-- name: SearchAssets :many
SELECT asset_id, owner_id, type, original_filename, storage_path, mime_type, file_size, content_hash, quick_fingerprint, quick_fingerprint_version, width, height, duration, upload_time, taken_time, capture_offset_minutes, is_deleted, deleted_at, specific_metadata, rating, liked, repository_id, status, updated_at, gps_latitude, gps_longitude, gps_geohash_5, gps_geohash_7, exif_raw FROM assets
WHERE is_deleted = false
AND (?1 IS NULL OR original_filename LIKE '%' || ?1 || '%')
AND (?2 IS NULL OR type = ?2)
ORDER BY upload_time DESC
LIMIT ?3 OFFSET ?4
`

type SearchAssetsParams struct {
	Column1 interface{} `db:"column_1" json:"column_1"`
	Column2 interface{} `db:"column_2" json:"column_2"`
	Limit   int64       `db:"limit" json:"limit"`
	Offset  int64       `db:"offset" json:"offset"`
}

func (q *Queries) SearchAssets(ctx context.Context, arg SearchAssetsParams) ([]Asset, error) {
	rows, err := q.db.QueryContext(ctx, searchAssets,
		arg.Column1,
		arg.Column2,
		arg.Limit,
		arg.Offset,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []Asset
	for rows.Next() {
		var i Asset
		if err := rows.Scan(
			&i.AssetID,
			&i.OwnerID,
			&i.Type,
			&i.OriginalFilename,
			&i.StoragePath,
			&i.MimeType,
			&i.FileSize,
			&i.ContentHash,
			&i.QuickFingerprint,
			&i.QuickFingerprintVersion,
			&i.Width,
			&i.Height,
			&i.Duration,
			&i.UploadTime,
			&i.TakenTime,
			&i.CaptureOffsetMinutes,
			&i.IsDeleted,
			&i.DeletedAt,
			&i.SpecificMetadata,
			&i.Rating,
			&i.Liked,
			&i.RepositoryID,
			&i.Status,
			&i.UpdatedAt,
			&i.GpsLatitude,
			&i.GpsLongitude,
			&i.GpsGeohash5,
			&i.GpsGeohash7,
			&i.ExifRaw,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

